from pathlib import Path
from PIL import Image
import json,hashlib,shutil
r=Path(__file__).resolve().parents[1]
entries=[('hati_howl','v02',128,3,118,'originals/hati_howl_v01_raw.png','https://chatgpt.com/c/6ad1a5d5-2374-83ea-8793-b252542ee99f',['Chrome ChatGPT reference-guided generation','Chrome Piskel actual selection copy/paste and PNG/piskel export','Pillow deterministic palette/alpha/size normalization and verification'],['通过 Piskel 实际选区复制，y>=62 区域及 x<=62,y<62 区域在三帧间的 RGBA 差异均为0。','只在头颈区域保留逐步仰头、张嘴；4倍接缝与1倍识别均已检查。']),('hrym_shield','v01',192,2,189,'originals/hrym_shield_v01_raw.png','https://chatgpt.com/c/6ad1a5ee-de04-83e9-aa28-536a3ba3e98b',['Chrome ChatGPT reference-guided generation','Pillow deterministic palette/alpha/size normalization'],['原冰盾由身体侧面移至胸前防御，冰锤始终在同一持握手中，武器与盔甲完整。','两帧为单次举盾技能；举盾时身体随防御姿态后收，循环首尾接回不适用。']),('hrym_stomp','v01',192,3,189,'originals/hrym_stomp_v01_raw.png','https://chatgpt.com/c/6ad1a603-a8ac-83ea-becd-5b0363a00c70',['Chrome ChatGPT reference-guided generation','Pillow deterministic palette/alpha/size normalization'],['原锤抬至头侧、向脚边下砸、收回，三个动作阶段清楚。','头顶冰冠、白胡须、肩毛、厚甲和原冰盾保留，锤头全程在格内，未画技能背景或地裂特效。','砸击有下蹲与展开站姿，不能将动作包围框高度变化解释为固定站姿抖动。'])]
for id,v,n,count,base,source,url,tools,observations in entries:
 path=r/f'candidates/{id}_{v}.png';im=Image.open(path).convert('RGBA');im.load();assert im.size==(n*count,n);frames=[im.crop((i*n,0,(i+1)*n,n)) for i in range(count)];colors=len({p[:3] for p in im.get_flattened_data() if p[3]});assert colors<=48;assert set(im.getchannel('A').get_flattened_data())=={0,255};boxes=[f.getbbox() for f in frames];assert all(b[0]>=2 and b[1]>=2 and b[2]<=n-2 and b[3]<=n-2 and b[3]==base+1 for b in boxes)
 ps=[]
 for f in frames:
  bg=Image.new('RGBA',(n,n),'#121721');bg.alpha_composite(f);ps.append(bg.resize((n*4,n*4),Image.Resampling.NEAREST).convert('RGB'))
 gif=f'previews/{id}_{v}.gif';dur=[120 if i%2==0 else 130 for i in range(count)];ps[0].save(r/gif,save_all=True,append_images=ps[1:],duration=dur,disposal=2)
 checks={k:True for k in ['exact_png_rgba_horizontal_frames_no_gaps','binary_alpha_no_semtransparent_edge','shared_character_palette_at_most_48','same_frame_size_baseline_and_safe_margins','same_character_anatomy_and_equipment','consistent_facing_right_three_quarter_view','dark_outline_and_upper_left_light','readable_on_121721_at_1x','all_frames_inspected_in_4x_contact','actual_chrome_different_animation_phases_observed','no_unintended_global_slide_or_detail_flicker_in_action','no_text_watermark_background','no_cut_weapons_or_limbs']}
 review=dict(id=id,status='self_check_passed_pending_batch_completion',candidate=f'candidates/{id}_{v}.png',preview=gif,source=source,generation_url=url,tools=tools,frame_size=[n,n],frames=count,size=list(im.size),colors=colors,alpha_values=[0,255],baseline=base,bboxes=boxes,checks=checks,loop_seam='not_applicable_single_play_skill',gif_nominal_fps=8,gif_duration_ms=dur,gif_actual_average_fps=count*1000/sum(dur),observations=observations,proof=['records/wave04_review_active_phase_a.png','records/wave04_review_active_phase_b.png'],game_test='not_performed',sha256=hashlib.sha256(path.read_bytes()).hexdigest())
 if id=='hati_howl':review.update(editable='candidates/hati_howl_v02.piskel',pixel_verification='records/hati_howl_v02_export_verification.json')
 (r/f'records/{id}_review.json').write_text(json.dumps(review,ensure_ascii=False,indent=2)+'\n');shutil.copy2(path,r/f'approved/{id}.png')
 print(id,review['status'])
